def validate_early_invu_fact(fact, role):
    """Closed INITIAL observation validation only; never derive private countdown."""
    if type(role) is not str or role not in ('invu:P', 'invu:O'):
        raise ValueError('exact early Invu role')
    _single_king_keys(fact, ('lineage', 'current', 'entry', 'parent_ready', 'private_provenance'), 'early Invu fact')
    lineage, entry, ready = fact['lineage'], fact['entry'], fact['parent_ready']
    _single_king_keys(lineage, ('timer_id', 'owner_id', 'kind', 'starts', 'stops', 'birth'), 'early lineage')
    _single_king_keys(entry, ('schema', 'ordinal', 'owner_inside_tree', 'owner_script', 'owner_scene', 'observer_ready_at_entry'), 'first entry')
    _single_king_keys(ready, ('schema', 'ordinal', 'starts', 'stops', 'state'), 'parent ready')
    if lineage['kind'] != 'Character.first_enter_tree/434' or entry['schema'] != 'phase434-invu-first-enter/1' or ready['schema'] != 'phase434-invu-parent-ready/1':
        raise ValueError('mixed early Invu protocol')
    if fact['private_provenance'] != 'pending-source-rule-first-enter-seed/1':
        raise ValueError('early observations are not private proof')
    for field in ('timer_id', 'owner_id'):
        value = lineage[field]
        if type(value) is not str or re.fullmatch('[1-9][0-9]{0,18}', value) is None or int(value) > (1 << 63) - 1:
            raise ValueError('early native identity')
    if lineage['timer_id'] == lineage['owner_id']:
        raise ValueError('Timer/owner alias')
    if entry['owner_inside_tree'] is not True or type(entry['observer_ready_at_entry']) is not bool:
        raise ValueError('actual entry readiness booleans')
    scene = 'res://Core/Player.tscn' if role == 'invu:P' else 'res://Core/Opponent.tscn'
    if entry['owner_script'] != 'res://Core/Character.gd' or entry['owner_scene'] != scene:
        raise ValueError('fixed Character source domain')
    if any(type(x['ordinal']) is not int or not 1 <= x['ordinal'] <= CAPS['native_ids'] * 2 for x in (entry, ready)) or entry['ordinal'] >= ready['ordinal']:
        raise ValueError('ordered local entry/ready ordinals')
    for phase in (lineage, ready):
        for field in ('starts', 'stops'):
            if type(phase[field]) is not int or not 0 <= phase[field] < (1 << 53):
                raise ValueError('strict bounded lifetime counter')
    if any(ready[field] > lineage[field] for field in ('starts', 'stops')):
        raise ValueError('lifetime counter reset')
    birth = _single_king_timer(lineage['birth'])
    checkpoint = _single_king_timer(ready['state'])
    current = _single_king_timer(fact['current'])
    for snapshot in (birth, checkpoint, current):
        node = snapshot['node']
        if node['native_id'] != lineage['timer_id'] or node['name'] != 'InvulnerabilityTimer' or node['role'] not in (None, role):
            raise ValueError('stable early native Timer identity')
        if _single_king_real(snapshot['wait_time']['binary64_be']) <= 0 or _single_king_real(snapshot['time_left']['binary64_be']) < 0:
            raise ValueError('native public Timer numeric domain')
        if len(node['positions']) > CAPS['depth']:
            raise ValueError('bounded early ancestry')
        for name in ('role', 'path', 'name', 'class'):
            if node[name] is not None and len(node[name].encode('utf-8')) > CAPS['string_utf8']:
                raise ValueError('bounded early node text')
    if birth['node']['inside_tree'] is not False or birth['node']['path'] is not None:
        raise ValueError('actual first child outside tree')
    if checkpoint['node']['inside_tree'] is not True or current['node']['inside_tree'] is not True or current['node']['role'] != role:
        raise ValueError('ready/current selected in-tree Timer')
    if any(not x['node']['path'].endswith('/InvulnerabilityTimer') for x in (checkpoint, current)):
        raise ValueError('direct named Timer path')
    # Counts and public states, including nonzero counts, are retained unchanged.
    # Constructor seed / NO_START eligibility is a separate SOURCE recipe gate.
    return fact

if role in ('invu:P', 'invu:O'):
    early = validate_early_invu_fact(facts['timers'][role], role)
    native = early['lineage']['timer_id']
    if native in timer_ids:raise ValueError('distinct early Timer identity')
